import{_ as a,o as n,c as e,a2 as p}from"./chunks/framework.DqYch1Cg.js";const b=JSON.parse('{"title":"NestJS 应用生命周期","description":"","frontmatter":{},"headers":[],"relativePath":"学习自测/18nestjs/q_nestjs_6-app_lifecycle.md","filePath":"学习自测/18nestjs/q_nestjs_6-app_lifecycle.md","lastUpdated":1794211306000}'),l={name:"学习自测/18nestjs/q_nestjs_6-app_lifecycle.md"};function i(t,s,r,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="nestjs-应用生命周期" tabindex="-1">NestJS 应用生命周期 <a class="header-anchor" href="#nestjs-应用生命周期" aria-label="Permalink to &quot;NestJS 应用生命周期&quot;">​</a></h1><blockquote><p>应用生命周期关注服务如何启动、运行和关闭；<a href="./q_nestjs_7-request_lifecycle">请求生命周期</a>关注一次请求如何被处理。</p></blockquote><h2 id="_1-nestjs-应用从启动到关闭的完整生命周期是什么" tabindex="-1">1. NestJS 应用从启动到关闭的完整生命周期是什么？ <a class="header-anchor" href="#_1-nestjs-应用从启动到关闭的完整生命周期是什么" aria-label="Permalink to &quot;1. NestJS 应用从启动到关闭的完整生命周期是什么？&quot;">​</a></h2><details class="details custom-block"><summary>参考回答</summary><p>NestJS 应用的生命周期，可以分成创建、初始化、运行和关闭四个阶段。</p><p>启动时，先在 <code>main.ts</code> 中调用 <code>NestFactory.create(AppModule)</code>，扫描模块、解析依赖并创建实例，再配置全局管道、拦截器等。</p><p>调用 <code>app.init()</code> 或 <code>app.listen()</code> 后，会先执行 <code>onModuleInit</code>，再执行 <code>onApplicationBootstrap</code>。如果调用的是 <code>listen()</code>，初始化完成后就开始监听端口、处理请求。</p><p>关闭时，可以主动调用 <code>app.close()</code>，也可以启用关闭钩子后接收系统关闭信号。顺序是 <code>onModuleDestroy</code>、<code>beforeApplicationShutdown</code>，然后关闭应用连接，最后执行 <code>onApplicationShutdown</code>。</p><p>这些钩子主要用来初始化和释放资源，异步钩子也会被等待。不过，完整的优雅停机，还要处理正在执行的请求、后台任务和数据库连接，不能只靠生命周期钩子。</p><p>如果有数据库，我会先停止接收新工作，等正在执行的请求和事务在限定时间内结束，再关闭连接池。这里关闭的是应用到数据库的连接，不是关闭 PostgreSQL 服务。数据库突然断连属于运行时故障，不会自动触发这些关闭钩子，需要另外处理超时、恢复连接，以及写操作重试时的幂等问题。</p></details><p><strong>回答节奏</strong>：先讲四个阶段，再按顺序说出五个钩子，控制在一到两分钟。涉及数据库时补充最后一段，整体控制在三分钟内。</p><p><strong>追问入口</strong>：<code>app.init()</code> 和 <code>app.listen()</code> 有什么区别？怎样让应用收到 <code>SIGTERM</code> 后执行清理？数据库断线时，正在执行的事务一定会回滚吗？</p><h2 id="完整流程" tabindex="-1">完整流程 <a class="header-anchor" href="#完整流程" aria-label="Permalink to &quot;完整流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>执行入口文件 main.ts</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>NestFactory.create(AppModule)</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>扫描模块、解析依赖关系</span></span>
<span class="line"><span>创建 Provider、Controller 等实例</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>配置应用</span></span>
<span class="line"><span>例如：全局 Pipe、Interceptor、CORS、关闭信号监听</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>调用 app.init() 或 app.listen()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>onModuleInit()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>onApplicationBootstrap()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>开始监听端口（调用 listen 时）</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>应用运行，处理请求</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>触发正常关闭</span></span>
<span class="line"><span>例如：app.close()，或启用关闭钩子后收到 SIGTERM</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>onModuleDestroy()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>beforeApplicationShutdown()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>关闭应用连接，例如 HTTP 服务</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>onApplicationShutdown()</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>应用关闭完成</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br></div></div><p><strong><code>NestFactory.create()</code> 会创建应用和依赖实例，但初始化生命周期钩子由后续的 <code>app.init()</code> 或 <code>app.listen()</code> 触发。</strong> <code>app.init()</code> 只初始化应用；<code>app.listen()</code> 会在需要时完成初始化，并开始监听端口。</p><h2 id="五个关键钩子" tabindex="-1">五个关键钩子 <a class="header-anchor" href="#五个关键钩子" aria-label="Permalink to &quot;五个关键钩子&quot;">​</a></h2><table tabindex="0"><thead><tr><th>钩子</th><th>触发时机</th><th>常见用途</th></tr></thead><tbody><tr><td><code>onModuleInit()</code></td><td>所在模块的依赖解析完成后，在应用初始化期间调用</td><td>初始化组件、建立数据库连接</td></tr><tr><td><code>onApplicationBootstrap()</code></td><td>所有模块初始化完成后、开始监听前</td><td>依赖整个应用完成初始化的启动工作</td></tr><tr><td><code>onModuleDestroy()</code></td><td>关闭流程开始时</td><td>停止组件工作、清理资源</td></tr><tr><td><code>beforeApplicationShutdown()</code></td><td>所有 <code>onModuleDestroy()</code> 完成后，关闭应用连接前</td><td>关闭前的协调和清理</td></tr><tr><td><code>onApplicationShutdown()</code></td><td>应用连接关闭后</td><td>最后的清理工作</td></tr></tbody></table><p>这描述的是阶段顺序，不代表不同模块、Provider 之间存在任意可依赖的固定调用顺序；初始化依赖应通过明确的依赖关系或协调逻辑表达。</p><h2 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h2><h3 id="异步钩子会被等待" tabindex="-1">异步钩子会被等待 <a class="header-anchor" href="#异步钩子会被等待" aria-label="Permalink to &quot;异步钩子会被等待&quot;">​</a></h3><p>钩子返回 Promise 时，Nest 会等待其完成。因此，关键初始化失败，可以阻止应用正常启动；关闭钩子也应避免无限等待。</p><h3 id="系统关闭信号需要显式启用" tabindex="-1">系统关闭信号需要显式启用 <a class="header-anchor" href="#系统关闭信号需要显式启用" aria-label="Permalink to &quot;系统关闭信号需要显式启用&quot;">​</a></h3><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { NestFactory } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@nestjs/core&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { AppModule } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;./app.module&#39;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bootstrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">() {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> app</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> NestFactory.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(AppModule)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">enableShutdownHooks</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> app.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listen</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bootstrap</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><code>app.close()</code> 可以主动触发关闭流程，不要求先调用 <code>enableShutdownHooks()</code>；<code>enableShutdownHooks()</code> 用于监听运行环境支持的系统关闭信号，例如 <code>SIGTERM</code>。</p><h3 id="关闭钩子不等于完整的优雅停机" tabindex="-1">关闭钩子不等于完整的优雅停机 <a class="header-anchor" href="#关闭钩子不等于完整的优雅停机" aria-label="Permalink to &quot;关闭钩子不等于完整的优雅停机&quot;">​</a></h3><p>数据库客户端、定时任务、消息消费者和后台任务，仍需按业务情况协调关闭。应考虑停止接收新工作、等待进行中的工作完成，再释放其依赖的资源，避免先断开数据库导致请求失败。</p><p><code>SIGKILL</code> 等强制终止不会给应用执行清理钩子的机会。<code>app.close()</code> 也不等于退出 Node.js 进程，未清理的定时器或后台任务仍可能让进程继续运行。</p><p><strong>请求作用域的 Provider 不参与这些应用生命周期钩子</strong>，因为它们的生命周期并不绑定到整个应用。</p><h2 id="有数据库时-应用如何安全下线" tabindex="-1">有数据库时，应用如何安全下线？ <a class="header-anchor" href="#有数据库时-应用如何安全下线" aria-label="Permalink to &quot;有数据库时，应用如何安全下线？&quot;">​</a></h2><p><strong>应用下线通常只关闭自己持有的数据库连接池，不关闭 PostgreSQL 服务。</strong> 数据库可能同时服务其他应用或其他实例；一个 NestJS 实例下线，不应影响它们。</p><h3 id="正常下线-先排空工作-再断开数据库" tabindex="-1">正常下线：先排空工作，再断开数据库 <a class="header-anchor" href="#正常下线-先排空工作-再断开数据库" aria-label="Permalink to &quot;正常下线：先排空工作，再断开数据库&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收到 SIGTERM，或主动开始下线</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>标记应用正在下线，让就绪检查不再通过</span></span>
<span class="line"><span>配合负载均衡摘流，拒绝新的业务工作</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>停止领取消息、启动新定时任务等后台工作</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>在限定时间内，等待已有请求和后台任务完成</span></span>
<span class="line"><span>事务正常完成时提交，失败时回滚</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>确认不再有工作使用数据库</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>关闭数据库客户端或连接池</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>完成剩余清理，进程退出</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>这是需要应用和部署环境共同实现的业务顺序，<strong>不是调用 <code>enableShutdownHooks()</code> 就会自动完成的流程</strong>。摘流可能存在传播延迟，应用也应有下线状态检查，避免继续接收新业务；具体关闭 HTTP 连接和等待请求的行为，还要结合 HTTP 适配器及版本验证。</p><p>连接管理上，长时间运行的 NestJS 服务通常复用默认单例 Provider 中的 Prisma Client 或连接池，<strong>不要每个请求都创建客户端、再调用 <code>$disconnect()</code></strong>，否则会造成连接反复建立和关闭。</p><h3 id="数据库连接放在哪个钩子里关闭" tabindex="-1">数据库连接放在哪个钩子里关闭？ <a class="header-anchor" href="#数据库连接放在哪个钩子里关闭" aria-label="Permalink to &quot;数据库连接放在哪个钩子里关闭？&quot;">​</a></h3><p>对自行管理的 Prisma Client，一种常见安排是：</p><ul><li>在前面的关闭阶段设置下线状态、停止后台任务，并等待它们退出。</li><li>HTTP 服务关闭、已有请求和后台任务均已处理后，在 <code>onApplicationShutdown()</code> 中 <code>await prisma.$disconnect()</code>，释放连接池。</li></ul><p><strong>关键是关闭数据库前，使用它的工作已经结束，不能只看钩子名字。</strong> 不要在 <code>onModuleDestroy()</code> 中不加协调地断开数据库，因为这时 HTTP 服务可能还未关闭，已有请求仍可能访问数据库。同样，若其他 Provider 的后续清理也需要数据库，就必须通过明确的协调逻辑保证它们先完成，不能依赖同一阶段各个钩子的偶然顺序。</p><p>若使用的 ORM 集成已经负责释放连接，应先确认它的关闭行为，避免与自定义逻辑冲突。关闭连接池不等于“替业务自动完成所有事务”，事务应由对应的业务逻辑提交或回滚。</p><h3 id="等待和清理都要有时间上限" tabindex="-1">等待和清理都要有时间上限 <a class="header-anchor" href="#等待和清理都要有时间上限" aria-label="Permalink to &quot;等待和清理都要有时间上限&quot;">​</a></h3><p>为请求、查询、事务和停机等待设置合理超时，并给部署平台留出足够的终止宽限时间。超过期限时，应记录未完成工作，按业务能力取消或中止，而不是一直等待。</p><p>仅用 <code>Promise.race()</code> 限时等待，并不会取消底层查询或任务；真正的中止能力取决于驱动、数据库超时设置和任务实现。不要一收到信号就调用 <code>process.exit()</code>，否则异步清理可能来不及完成。</p><h2 id="突然掉线或被强制终止-数据库会怎样" tabindex="-1">突然掉线或被强制终止，数据库会怎样？ <a class="header-anchor" href="#突然掉线或被强制终止-数据库会怎样" aria-label="Permalink to &quot;突然掉线或被强制终止，数据库会怎样？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>是否执行应用关闭钩子</th><th>处理重点</th></tr></thead><tbody><tr><td>应用正常下线</td><td>主动 <code>app.close()</code>，或启用关闭钩子后收到支持的信号时执行</td><td>摘流、排空工作、关闭连接池</td></tr><tr><td>数据库重启、网络中断</td><td>不会仅因断连自动执行</td><td>查询超时与错误处理、连接恢复、有限重试</td></tr><tr><td>应用崩溃、断电或被 <code>SIGKILL</code></td><td>无法保证执行，<code>SIGKILL</code> 不会执行</td><td>数据库检测断连后清理会话；重启后核对未完成业务</td></tr></tbody></table><h3 id="数据库断连-先处理失败-再考虑恢复" tabindex="-1">数据库断连：先处理失败，再考虑恢复 <a class="header-anchor" href="#数据库断连-先处理失败-再考虑恢复" aria-label="Permalink to &quot;数据库断连：先处理失败，再考虑恢复&quot;">​</a></h3><p>当前查询或事务可能报错，也可能直到超时才发现连接不可用。应用应记录错误，对依赖数据库且暂时无法处理的请求返回适当的失败响应，例如 503；故障持续时，可将就绪检查标记为失败，避免持续承接无法完成的请求。</p><p>连接恢复方式取决于 Prisma、驱动或连接池的版本和配置，不能承诺所有查询都会自动重连并重试成功。通常让连接池淘汰失效连接、按需建立新连接；确实需要业务重试时，应设置次数上限、退避和抖动，避免故障期间大量实例同时重试。</p><p><strong>不要捕获到任意数据库错误就销毁并重建整个连接池。</strong> 这可能影响其他正在执行的请求；先区分连接故障、约束冲突等错误，只对适合恢复的临时故障采取重试。</p><h3 id="会话结束-未提交事务会回滚-但不能据此盲目重试写入" tabindex="-1">会话结束：未提交事务会回滚，但不能据此盲目重试写入 <a class="header-anchor" href="#会话结束-未提交事务会回滚-但不能据此盲目重试写入" aria-label="Permalink to &quot;会话结束：未提交事务会回滚，但不能据此盲目重试写入&quot;">​</a></h3><p>PostgreSQL 检测到连接结束并终止会话时，会回滚仍然打开、尚未提交的事务，并释放相关事务锁。网络中断不一定会被立即检测到，清理可能受到 TCP 检测及数据库超时设置的影响。</p><p>需要区分两个情况：</p><ul><li><strong>事务仍未提交</strong>：会话结束时由数据库回滚，重连也不能继续原来的事务。</li><li><strong>提交已发生，但响应没收到</strong>：应用看到超时或断线，数据库里的修改却可能已经提交；自动提交的写操作也可能在数据库察觉断连前完成。</li></ul><p>所以，<strong>“没收到成功响应”不等于“写入没有成功”</strong>。涉及保存、扣减等操作，应结合幂等键、唯一约束或版本条件更新，在必要时查询结果后再决定是否重试，避免重复写入。</p><p>应用进程被强制终止时，操作系统通常会回收它的套接字，数据库再按上述规则清理会话；不应把这个兜底机制当作正常停机方案。应用停机也不会自动回滚此前已经提交的业务数据。</p><h2 id="学习场景-nestjs-prisma-postgresql" tabindex="-1">学习场景：NestJS + Prisma + PostgreSQL <a class="header-anchor" href="#学习场景-nestjs-prisma-postgresql" aria-label="Permalink to &quot;学习场景：NestJS + Prisma + PostgreSQL&quot;">​</a></h2><p>假设后续实现一个“保存学习笔记”的后端服务：</p><ul><li>启动时：可以在初始化钩子中调用 Prisma 的 <code>$connect()</code>，提前确认数据库连接可用。</li><li>运行时：处理笔记读取、保存等请求。</li><li>正常下线时：停止接收新的保存请求和后台任务，等待已接收的工作在限定时间内完成，再调用 <code>$disconnect()</code> 释放连接池。</li><li>突然断线时：记录失败并处理超时；如果保存结果不确定，利用笔记 ID、请求幂等键或版本号核对结果，再决定是否重试。</li></ul><p>显式调用 <code>$connect()</code> 是一种初始化选择；Prisma 也可以在第一次查询时建立连接，并非必须依靠该钩子。</p><h2 id="记忆主线" tabindex="-1">记忆主线 <a class="header-anchor" href="#记忆主线" aria-label="Permalink to &quot;记忆主线&quot;">​</a></h2><p><strong>创建依赖 → 初始化 → 监听运行 → 关闭清理。</strong></p><p><strong>数据库关闭顺序：停止新工作 → 等待已有工作 → 关闭连接池。断线后先判断结果，写操作不能盲目重试。</strong></p><blockquote><p>来源：<a href="https://docs.nestjs.com/fundamentals/lifecycle-events" target="_blank" rel="noreferrer">NestJS 官方文档：Lifecycle events</a></p></blockquote><blockquote><p>来源：<a href="https://www.prisma.io/docs/orm/prisma-client/setup-and-configuration/databases-connections/connection-management" target="_blank" rel="noreferrer">Prisma 官方文档：Connection management</a></p></blockquote><blockquote><p>来源：<a href="https://www.postgresql.org/docs/current/protocol-flow.html#PROTOCOL-FLOW-TERMINATION" target="_blank" rel="noreferrer">PostgreSQL 官方文档：Protocol flow — Termination</a></p></blockquote>`,58)])])}const u=a(l,[["render",i]]);export{b as __pageData,u as default};
